"src/hummod_myocardial_sid_source_aligned.js":function(module,exports,require){
'use strict';

// Exact HumMod intracellular SID algebra used by myocardial pH.
// Pinned source:
// riliescu/hummod-standalone@8dab57e05631f779bf5020fe0dd51874d8ae98c1
// Structure/Electrolytes/CellSID.DES
// Structure/LeftHeart/LeftHeart-Ph.DES
// Structure/RightHeart/RightHeart-Ph.DES

function finite(v,label){
  if(typeof v!=='number'||!Number.isFinite(v)) throw new Error(label+' must be finite');
  return v;
}

const CELL_SID_WEAK_ANIONS=0.036;
const CELL_SID_STRONG_ANIONS=0.117;
const CELL_SID_OTHER_CATIONS=0.012;

function cellSidLessLactate({
  intracellularPotassium,
  otherCations=CELL_SID_OTHER_CATIONS,
  strongAnions=CELL_SID_STRONG_ANIONS,
}={}){
  finite(intracellularPotassium,'intracellularPotassium');
  finite(otherCations,'otherCations');
  finite(strongAnions,'strongAnions');
  return intracellularPotassium+otherCations-strongAnions;
}

function myocardialSid({
  intracellularPotassium,
  myocardialLactate,
  otherCations=CELL_SID_OTHER_CATIONS,
  strongAnions=CELL_SID_STRONG_ANIONS,
}={}){
  finite(myocardialLactate,'myocardialLactate');
  const lessLactate=cellSidLessLactate({
    intracellularPotassium,
    otherCations,
    strongAnions,
  });
  const sid=lessLactate-myocardialLactate;
  return Object.freeze({
    sid,
    sidMeqPerL:1000*sid,
    lessLactate,
    intracellularPotassium,
    myocardialLactate,
    otherCations,
    strongAnions,
  });
}

module.exports={
  CELL_SID_WEAK_ANIONS,
  CELL_SID_STRONG_ANIONS,
  CELL_SID_OTHER_CATIONS,
  cellSidLessLactate,
  myocardialSid,
};

},
"src/hummod_myocardial_co2_source_aligned.js":function(module,exports,require){
'use strict';

// Exact source-aligned HumMod myocardial CO2/bicarbonate mass-balance primitive.
// Pinned source:
// riliescu/hummod-standalone@8dab57e05631f779bf5020fe0dd51874d8ae98c1
// Structure/LeftHeart/LeftHeart-CO2.DES
// Structure/RightHeart/RightHeart-CO2.DES
// Structure/CO2/CO2Tools.DES
// Structure/Metabolism/Metabolism-RespiratoryQuotient.DES

const {
  tissueBaseToGas,
  bloodGasToBase,
}=require("src/hummod_acid_base_source_aligned.js");

function finite(v,label){
  if(typeof v!=='number'||!Number.isFinite(v)) throw new Error(label+' must be finite');
  return v;
}
function positive(v,label){
  finite(v,label);
  if(!(v>0)) throw new Error(label+' must be > 0');
  return v;
}
function nonNegative(v,label){
  finite(v,label);
  if(v<0) throw new Error(label+' must be >= 0');
  return v;
}

const LITERS_TO_MOLS=0.0446;
const RESPIRATORY_QUOTIENT=0.8;

const HEART_CONFIG=Object.freeze({
  left:Object.freeze({initialMass:3.5,errorLimit:0.04}),
  right:Object.freeze({initialMass:0.6,errorLimit:0.01}),
});

function calculateMyocardialCo2Derivatives({
  side,
  mass,
  liquidVolumeMl,
  tissueSid,
  bloodFlowMlPerMin,
  o2UseMlPerMin,
  bloodSid,
  arterialHco3,
  dxMin,
  dxUndefined=false,
  respiratoryQuotient=RESPIRATORY_QUOTIENT,
}={}){
  if(side!=='left'&&side!=='right') throw new Error('side must be left or right');
  nonNegative(mass,'mass');
  positive(liquidVolumeMl,'liquidVolumeMl');
  nonNegative(bloodFlowMlPerMin,'bloodFlowMlPerMin');
  nonNegative(o2UseMlPerMin,'o2UseMlPerMin');
  finite(tissueSid,'tissueSid');
  finite(bloodSid,'bloodSid');
  finite(arterialHco3,'arterialHco3');
  finite(respiratoryQuotient,'respiratoryQuotient');
  if(!dxUndefined) positive(dxMin,'dxMin');

  const hco3=mass/liquidVolumeMl;
  const hco3MeqPerL=1000*hco3;
  const pCO2=tissueBaseToGas({hco3,SID:tissueSid}).pCO2;
  const k=bloodFlowMlPerMin/liquidVolumeMl;

  let alpha;
  if(dxUndefined){
    alpha=0;
  } else if((k*dxMin)>=100){
    alpha=4e-44;
  } else {
    alpha=Math.exp(-k*dxMin);
  }

  const inflowGas=respiratoryQuotient*o2UseMlPerMin;
  const inflowBase=LITERS_TO_MOLS*inflowGas;
  const bloodHco3=bloodGasToBase({pCO2,SID:bloodSid}).hco3;
  const outflow0=bloodFlowMlPerMin*(bloodHco3-arterialHco3);
  const outflowBase=(alpha*outflow0)+((1-alpha)*inflowBase);
  const change=inflowBase-outflowBase;

  return Object.freeze({
    side,
    mass,
    hco3,
    hco3MeqPerL,
    pCO2,
    k,
    alpha,
    inflowGas,
    inflowBase,
    bloodHco3,
    outflow0,
    outflowBase,
    change,
    source:Object.freeze({
      initialMass:HEART_CONFIG[side].initialMass,
      errorLimit:HEART_CONFIG[side].errorLimit,
      litersToMols:LITERS_TO_MOLS,
      respiratoryQuotient,
    }),
  });
}

function eulerStepMyocardialCo2(args){
  const d=calculateMyocardialCo2Derivatives(args);
  if(args.dxUndefined) return Object.freeze({...d,nextMass:d.mass});
  return Object.freeze({...d,nextMass:d.mass+d.change*args.dxMin});
}

module.exports={
  LITERS_TO_MOLS,
  RESPIRATORY_QUOTIENT,
  HEART_CONFIG,
  calculateMyocardialCo2Derivatives,
  eulerStepMyocardialCo2,
};

},
"src/hummod_acid_base_source_aligned.js":function(module,exports,require){
'use strict';

// Exact HumMod acid-base primitives required by myocardial pH.
// Pinned source:
// riliescu/hummod-standalone@8dab57e05631f779bf5020fe0dd51874d8ae98c1
// Structure/AcidBase/PhGeneral.DES
// Structure/AcidBase/PhCells.DES
// Structure/CO2/Blood-GasToBase.DES
// Structure/CO2/Tissue-BaseToGas.DES

function finite(v,label){
  if(typeof v!=='number'||!Number.isFinite(v)) throw new Error(label+' must be finite');
  return v;
}

const PH_CELLS_PK=7.15;
const BLOOD_GAS_TO_BASE_A=0.2325;
const BLOOD_GAS_TO_BASE_B=0.00036;
const TISSUE_BASE_TO_GAS_C=-1411.4;
const TISSUE_BASE_TO_GAS_D=5988.0;

function phGeneral({pK,pCO2,SID}={}){
  finite(pK,'pK'); finite(pCO2,'pCO2'); finite(SID,'SID');
  let pH;
  if(pCO2<=0){
    pH=pK+3;
  } else if((SID/pCO2)<1e-3){
    pH=pK-3;
  } else {
    pH=pK+Math.log10(SID/pCO2);
  }
  const hydrogen=10**(9-pH);
  return Object.freeze({pH,hydrogen});
}

function phCells({pCO2,SID}={}){
  return phGeneral({pK:PH_CELLS_PK,pCO2,SID});
}

function bloodGasToBase({pCO2,SID}={}){
  finite(pCO2,'pCO2'); finite(SID,'SID');
  const hco3=(pCO2>0&&SID>0)
    ? (BLOOD_GAS_TO_BASE_A*SID)+(BLOOD_GAS_TO_BASE_B*pCO2)
    : 0.0001;
  return Object.freeze({hco3});
}

function tissueBaseToGas({hco3,SID}={}){
  finite(hco3,'hco3'); finite(SID,'SID');
  const pCO2=(hco3>0&&SID>0)
    ? Math.max((TISSUE_BASE_TO_GAS_C*SID)+(TISSUE_BASE_TO_GAS_D*hco3),0.0001)
    : 0.0001;
  return Object.freeze({pCO2});
}

module.exports={
  PH_CELLS_PK,
  BLOOD_GAS_TO_BASE_A,
  BLOOD_GAS_TO_BASE_B,
  TISSUE_BASE_TO_GAS_C,
  TISSUE_BASE_TO_GAS_D,
  phGeneral,
  phCells,
  bloodGasToBase,
  tissueBaseToGas,
};

},
