          sourceQualified:true,
          alveolarVolumeL:coordinate.alveolarVolumeL,
          alveolarPressureMmHg:coordinate.alveolarPressureMmHg,
          pleuralPressureMmHg:coordinate.pleuralPressureMmHg,
